import{_ as e,o as r,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"智能体常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/faq.md","filePath":"guide/agent/faq.md","lastUpdated":1789295632000}'),o={name:"guide/agent/faq.md"};function n(l,a,h,d,s,u){return r(),t("div",null,[...a[0]||(a[0]=[i('<h1 id="智能体常见问题" tabindex="-1">智能体常见问题 <a class="header-anchor" href="#智能体常见问题" aria-label="Permalink to &quot;智能体常见问题&quot;">​</a></h1><p>游玩和创作中的高频问题。站内其他问题（如 429 限流、令牌泄露）见<a href="/guide/faq">站点 FAQ</a>。</p><h2 id="提示「余额不足-无法发送」" tabindex="-1">提示「余额不足，无法发送」 <a class="header-anchor" href="#提示「余额不足-无法发送」" aria-label="Permalink to &quot;提示「余额不足，无法发送」&quot;">​</a></h2><p>额度用完了。去「我的用量」每日签到或兑换卡密，见<a href="/guide/agent/usage">用量与额度</a>。</p><h2 id="回复生成失败怎么办" tabindex="-1">回复生成失败怎么办 <a class="header-anchor" href="#回复生成失败怎么办" aria-label="Permalink to &quot;回复生成失败怎么办&quot;">​</a></h2><p>失败原因会标注在提示上（请求超时 / 上游请求失败等）。你发送的内容会退回输入框，<strong>直接重试即可</strong>，失败的那次不会计费。频繁超时可以尝试缩短上下文（见下一条）或换一个模型；持续失败请联系管理员并提供错误码。</p><h2 id="角色是不是忘了我们之前聊的" tabindex="-1">角色是不是忘了我们之前聊的？ <a class="header-anchor" href="#角色是不是忘了我们之前聊的" aria-label="Permalink to &quot;角色是不是忘了我们之前聊的？&quot;">​</a></h2><p>先看界面上有没有<a href="/guide/agent/chat#消息">上下文边界</a>：边界以上的消息不再原文发给模型，这是正常的省费机制。想让角色「记住」窗口之外的内容：</p><ul><li>开启<a href="/guide/agent/memory">记忆</a>（语义记忆或压缩便签）。</li><li>创作者侧：把关键设定写进<a href="/guide/agent/worldbook">世界书</a>，命中即注入。</li></ul><h2 id="记忆开了但感觉没用" tabindex="-1">记忆开了但感觉没用 <a class="header-anchor" href="#记忆开了但感觉没用" aria-label="Permalink to &quot;记忆开了但感觉没用&quot;">​</a></h2><p>在「记忆」页调整参数：提高<strong>检索条数</strong>、降低<strong>最低相关度</strong>（过滤太狠会什么都召回不了）。另外记忆按会话隔离，换会话就是空白，不是丢档。</p><h2 id="切换压缩模型后便签不见了" tabindex="-1">切换压缩模型后便签不见了 <a class="header-anchor" href="#切换压缩模型后便签不见了" aria-label="Permalink to &quot;切换压缩模型后便签不见了&quot;">​</a></h2><p>预期行为：切换压缩模型会清空当前会话的便签缓存并重新压缩。换模型前想清楚，或先导出聊天记录备份。</p><h2 id="删除会话会删掉什么" tabindex="-1">删除会话会删掉什么 <a class="header-anchor" href="#删除会话会删掉什么" aria-label="Permalink to &quot;删除会话会删掉什么&quot;">​</a></h2><p>私信记录、压缩便签、绑定的云端记忆条目会<strong>一并删除且不可恢复</strong>；只有模型调用流水保留。想保留剧情先导出聊天记录（「会话」标签页 → 导出）。</p><h2 id="消息发不出去-提示先选择对话风格" tabindex="-1">消息发不出去，提示先选择对话风格 <a class="header-anchor" href="#消息发不出去-提示先选择对话风格" aria-label="Permalink to &quot;消息发不出去，提示先选择对话风格&quot;">​</a></h2><p>社区游玩必须先有可用的<a href="/guide/agent/styles">对话风格</a>。去风格广场加一个，或自己创建一份。</p><h2 id="生图失败-图片没保存" tabindex="-1">生图失败 / 图片没保存 <a class="header-anchor" href="#生图失败-图片没保存" aria-label="Permalink to &quot;生图失败 / 图片没保存&quot;">​</a></h2><p>按提示对症处理：</p><ul><li><strong>内容审核拦截</strong>：不合规内容不会出图，调整对话方向。</li><li><strong>网盘空间不足</strong>：清理网盘后再试。</li><li><strong>文件类型不允许 / 超过大小限制</strong>：账号的上传策略限制。</li><li><strong>额度不足</strong>：先补充额度。</li><li>部分图片指令超出每轮自动生成上限，需要手动点击生成。</li></ul><h2 id="角色表情包发不出来" tabindex="-1">角色表情包发不出来 <a class="header-anchor" href="#角色表情包发不出来" aria-label="Permalink to &quot;角色表情包发不出来&quot;">​</a></h2><p>排查顺序：角色的表情包功能是否开启 → 每轮上限是否为 0（0 表示关闭）→ 全站表情是否由管理员填写了「智能体描述」。细节见<a href="/guide/agent/regex-stickers">正则与表情包</a>。</p><h2 id="我提交的角色没通过审核" tabindex="-1">我提交的角色没通过审核 <a class="header-anchor" href="#我提交的角色没通过审核" aria-label="Permalink to &quot;我提交的角色没通过审核&quot;">​</a></h2><p>未通过的作品会显示外审反馈的问题分类和原因。按反馈修改内容后重新提交即可。高频原因：露骨色情、暴力描写越线、诱导性内容。见<a href="/guide/agent/create#安全与边界">创作角色 · 安全与边界</a>。</p><h2 id="会话或角色显示「已被封禁」" tabindex="-1">会话或角色显示「已被封禁」 <a class="header-anchor" href="#会话或角色显示「已被封禁」" aria-label="Permalink to &quot;会话或角色显示「已被封禁」&quot;">​</a></h2><p>管理员处置。被封禁的角色/会话无法继续对话或修改设置；会话级封禁连历史记录也看不到（删除前可导出）。认为误判请联系管理员。</p><h2 id="测试会话和社区会话有什么区别" tabindex="-1">测试会话和社区会话有什么区别 <a class="header-anchor" href="#测试会话和社区会话有什么区别" aria-label="Permalink to &quot;测试会话和社区会话有什么区别&quot;">​</a></h2><p><a href="/guide/agent/quick-start#草稿测试与社区游玩">草稿测试</a>只有你自己可见，用来验证设定；社区会话是和已发布角色的对话。功能一致，删除时都会清掉对应记忆。</p><h2 id="怎么让角色用某种格式回复-表格、代码块" tabindex="-1">怎么让角色用某种格式回复（表格、代码块……） <a class="header-anchor" href="#怎么让角色用某种格式回复-表格、代码块" aria-label="Permalink to &quot;怎么让角色用某种格式回复（表格、代码块……）&quot;">​</a></h2><p>对话气泡支持 Markdown。创作者可以在角色的人设、示例对话或风格正文里写明输出格式要求；用户也可以直接在消息里提出格式要求。语法见<a href="/guide/agent/syntax">对话语法</a>。</p>',30)])])}const p=e(o,[["render",n]]);export{g as __pageData,p as default};
